import numpy as np
def extract_features(image):
 image=np.asarray(image,dtype=float)
 return np.array([np.mean(image),np.std(image),np.min(image),np.max(image),np.median(image),np.mean(np.abs(np.diff(image,axis=0))),np.mean(np.abs(np.diff(image,axis=1))),np.mean(image>np.mean(image))],dtype=float)

